"""Writes src/logic/py-data.ts: the data Python's html.unescape uses (the HTML5 named character references and the
rules for invalid numeric ones), taken from Python itself, so the port unescapes exactly as the Python app did.
Run from site/:  python scripts/make-py-data.py"""
import html
import html.entities
import json
import sys

out = [
    "// Generated by scripts/make-py-data.py from Python " + sys.version.split()[0] + "'s html module. Don't edit by hand.",
    "/* eslint-disable */",
    "/** html.entities.html5: every HTML5 named character reference, with and without its semicolon where HTML allows. */",
    "export const HTML5: Record<string, string> = " + json.dumps(html.entities.html5, ensure_ascii=True, sort_keys=True) + ";",
    "/** html._invalid_charrefs: numeric references HTML5 maps to another character. */",
    "export const INVALID_CHARREFS: Record<number, string> = "
    + json.dumps({str(k): v for k, v in sorted(html._invalid_charrefs.items())}, ensure_ascii=True) + ";",
    "/** html._invalid_codepoints: numeric references HTML5 drops. */",
    "export const INVALID_CODEPOINTS = new Set<number>(" + json.dumps(sorted(html._invalid_codepoints)) + ");",
    "",
]
with open("src/logic/py-data.ts", "w", encoding="utf-8", newline="\n") as f:
    f.write("\n".join(out))
